 import {WorkerClient} from "./WorkerClient"

+export const EventBusMessageType = Object.freeze({
+	EntityUpdate: "EntityUpdate",
+	UnreadCounterUpdate: "UnreadCounterUpdate",
+} as const)
+
 export class EventBusClient {
 	private _ws: WebSocket | null = null
 	private _reconnectTimeout: TimeoutID | null = null
+	private _entityUpdateQueue: Promise<void> = Promise.resolve()

 	constructor(
 		private readonly _worker: WorkerClient,
@@ -12,16 +17,20 @@ export class EventBusClient {
 	) {}

-	private handleMessage(event: MessageEvent): void {
+	handleEntityEvent(event: MessageEvent): void {
 		const msg: any = JSON.parse(event.data)
-		if (msg.type === "EntityUpdate") {
-			this._worker.entityEvent(msg.data)
-		} else if (msg.type === "UnreadCounterUpdate") {
+		if (msg.type === EventBusMessageType.EntityUpdate) {
+			this._entityUpdateQueue = this._entityUpdateQueue
+				.then(() => this._worker.entityEvent(msg.data))
+				.catch(e => console.log("entity update failed", e))
+		} else if (msg.type === EventBusMessageType.UnreadCounterUpdate) {
 			this._worker.unreadCounterUpdate(msg.data)
 		}
 	}

 	connect(): Promise<void> {
 		return new Promise((resolve, reject) => {
 			this._ws = new WebSocket(this._url)
-			this._ws.onmessage = (event: MessageEvent) => this.handleMessage(event)
+			this._ws.onmessage = (event: MessageEvent) => this.handleEntityEvent(event)
 			this._ws.onopen = () => resolve()
 			this._ws.onclose = (event: CloseEvent) => this.onClose(event)
 			this._ws.onerror = (event: Event) => reject(event)

